package dev.pathland.view.state;

import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

/**
 * An in-memory {@link StateStore}. Thread-safe ({@link ConcurrentHashMap}), so server
 * apps can read state from request threads while a session actor writes it. Zero
 * dependencies; the fallback when no durable backend is configured.
 */
public final class InMemoryStateStore implements StateStore {

    private final ConcurrentMap<String, Object> states = new ConcurrentHashMap<>();

    @Override
    public <T> Optional<T> load(String key, Class<T> clazz) {
        Object value = states.get(key);
        if (value != null && clazz.isInstance(value)) {
            return Optional.of(clazz.cast(value));
        }
        return Optional.empty();
    }

    @Override
    public void save(String key, Object state) {
        states.put(key, state);
    }

    @Override
    public void delete(String key) {
        states.remove(key);
    }

    @Override
    public String toString() {
        return "InMemoryStateStore(" + states.size() + " keys)";
    }
}

package dev.pathland.view;

/**
 * Platform-level environment values and helpers (spec DSL.md §4.5). Unlike
 * {@code Navigation.ROUTER} (the router *instance*, only present when navigation is
 * declared), the active platform path is provided by the host for **every** app —
 * with or without navigation — so any app can observe the current path (a web URL, a
 * native deep link / open event, the initial route) like {@code onOpenURL},
 * generalized across platforms.
 *
 * <pre>{@code
 * // host (always):
 * WritableSignal<String> activePath = Signals.signal(env.route());
 * emitter.mount(
 *         root.modifiers(environmentBinding(e -> e.key(Platform.ACTIVE_PATH).value(activePath))),
 *         env);
 *
 * // app — with or without navigation:
 * view.modifiers(pathChange(p -> p.listener(path -> handlePlatformPath(path))));
 * }</pre>
 */
public final class Platform {

    /**
     * The environment key for the app's active platform path. The host injects a
     * writable signal; {@code Environment.value(ACTIVE_PATH)} returns it as a
     * {@code Signal<String>} (the same instance, so it stays reactive), and a bound
     * router reads it for external writes and mirrors navigation back into it.
     */
    public static final EnvironmentKey<String> ACTIVE_PATH = EnvironmentKey.of("platform.activePath");

    private Platform() {}
}

