package dev.pathland.view.signal;

import java.util.ArrayDeque;
import java.util.Objects;
import java.util.function.BiPredicate;
import java.util.function.Supplier;

/**
 * Factory for Angular-style reactive primitives:
 *
 * <pre>{@code
 * WritableSignal<Integer> count = Signals.signal(0);
 * Signal<String> label = Signals.computed(() -> "Count: " + count.get());
 * EffectRef e = Signals.effect(() -> emit(label.get()));
 * count.set(1); // synchronously flushes the effect
 * e.destroy();
 * int n = Signals.untracked(() -> count.get()); // no dependency recorded
 * }</pre>
 *
 * <p>Equality defaults to {@link Objects#equals}. Effects flush synchronously at the
 * end of the outermost write. Signals are single-threaded by contract.
 */
public final class Signals {

    private Signals() {}

    /** A writable signal with {@link Objects#equals} equality. */
    public static <T> WritableSignal<T> signal(T initial) {
        return new WritableSignalImpl<>(initial, Objects::equals, null);
    }

    /** A writable signal with a custom equality comparator. */
    public static <T> WritableSignal<T> signal(T initial, BiPredicate<T, T> equal) {
        return new WritableSignalImpl<>(initial, Objects.requireNonNull(equal, "equal"), null);
    }

    /** A named writable signal (names surface in dependency errors). */
    public static <T> WritableSignal<T> signal(String name, T initial) {
        return new WritableSignalImpl<>(initial, Objects::equals, name);
    }

    /**
     * An immutable signal whose value never changes. Used to give a view a single
     * {@link Signal} field while still authoring static values ergonomically
     * ({@code Text.make("...")} ≡ {@code Text.make(Signals.constant("..."))}). The emitter
     * treats a constant as a plain (non-reactive) property — no binding/effect.
     */
    public static <T> Signal<T> constant(T value) {
        return new ConstantSignal<>(value);
    }

    /** A lazy, memoized derived signal. */
    public static <T> Signal<T> computed(Supplier<T> fn) {
        return new ComputedSignal<>(Objects.requireNonNull(fn, "computed body"), Objects::equals);
    }

    /** A derived signal with a custom equality comparator. */
    public static <T> Signal<T> computed(Supplier<T> fn, BiPredicate<T, T> equal) {
        return new ComputedSignal<>(
                Objects.requireNonNull(fn, "computed body"), Objects.requireNonNull(equal, "equal"));
    }

    /** Register an effect; runs immediately, then on tracked dependency changes. */
    public static EffectRef effect(Runnable fn) {
        return effect(fn, EffectOptions.DEFAULT);
    }

    /** Register an effect with options. */
    public static EffectRef effect(Runnable fn, EffectOptions options) {
        return new Effect(
                Objects.requireNonNull(fn, "effect body"),
                Objects.requireNonNull(options, "options"),
                null);
    }

    /** A named effect. */
    public static EffectRef effect(String name, Runnable fn) {
        return new Effect(Objects.requireNonNull(fn, "effect body"), EffectOptions.DEFAULT, name);
    }

    /**
     * Read signals without recording dependencies on the enclosing context. Any
     * signals read inside {@code fn} are not tracked, so the surrounding computed or
     * effect will not re-run when they change.
     */
    public static <T> T untracked(Supplier<T> fn) {
        ArrayDeque<ReactiveNode> stack = ReactiveContext.stack();
        ArrayDeque<ReactiveNode> saved = new ArrayDeque<>(stack);
        stack.clear();
        try {
            return Objects.requireNonNull(fn, "untracked body").get();
        } finally {
            stack.addAll(saved);
        }
    }
}

package dev.pathland.view;

import dev.pathland.view.signal.Signal;

/**
 * The rendering environment — the single inheritance/scoping mechanism in the DSL.
 * Carries a hierarchical scope of {@link EnvironmentValues} keyed by
 * {@link EnvironmentKey} ({@code EnvironmentValues} style): a parent injects
 * a value down the entire child tree via the {@link EnvironmentBinding} modifier
 * value, and any descendant reads it with {@link #value(EnvironmentKey)}.
 *
 * <p>{@link EnvironmentBinding} binds a value for the subtree it
 * wraps — nearest wins, so an inner binding overrides an outer one. The mount render
 * is synchronous and single-threaded, so a {@link ThreadLocal} is equivalent to
 * ScopedValue here while keeping the library on every LTS from Java 17. This
 * thread-local is the <em>implementation</em> of the environment, never a parallel
 * mechanism: no modifier may scope values by any other route.
 *
 * <p>Reads always return a signal ({@link #value(EnvironmentKey)}): a value injected
 * as a {@link Signal} comes back as the same instance (bindable for reactive updates),
 * a plain value is wrapped in a constant signal, and a read made before the key is
 * bound (e.g. a field initializer) is a lazy signal resolved at render time.
 *
 * <p>Structural slots re-render their destination outside the container's render
 * path ({@code Emitter.reconcileSlot}); each node captures its incoming scope
 * ({@code PathlandNode.environmentForChildren}) so destinations that read a value
 * keep working on every re-render — including scoped styles like {@link #BUTTON_STYLE}.
 */
public final class Environment {

    /**
     * The environment key for the active {@link ButtonStyle} ({@code .buttonStyle}).
     * {@code ButtonStyle} (a {@code Style} — the value is the modifier) scopes it down the wrapped subtree via the generic
     * environment; {@link Button} reads it with {@link #buttonStyle()}
     * (defaulting to {@link PlainButtonStyle}).
     */
    public static final EnvironmentKey<ButtonStyle> BUTTON_STYLE = EnvironmentKey.of("buttonStyle");

    /**
     * The environment key for the active {@link LabelStyle} ({@code .labelStyle}).
     * {@code LabelStyle} (a {@code Style} — the value is the modifier) scopes it down the wrapped subtree via the generic
     * environment; {@link Label} reads it with {@link #labelStyle()}
     * (defaulting to {@link DefaultLabelStyle}).
     */
    public static final EnvironmentKey<LabelStyle> LABEL_STYLE = EnvironmentKey.of("labelStyle");

    /**
     * The environment key for the active {@link AudioStyle} ({@code .audioStyle}).
     * {@code AudioStyle} (a {@code Style} — the value is the modifier) scopes it down the wrapped subtree; {@link Audio} reads
     * it with {@link #audioStyle()} (defaulting to
     * {@link NativeAudioStyle}).
     */
    public static final EnvironmentKey<AudioStyle> AUDIO_STYLE = EnvironmentKey.of("audioStyle");

    /**
     * The environment key for the active {@link VideoStyle} ({@code .videoStyle}).
     * {@code VideoStyle} (a {@code Style} — the value is the modifier) scopes it down the wrapped subtree; {@link Video} reads
     * it with {@link #videoStyle()} (defaulting to
     * {@link NativeVideoStyle}).
     */
    public static final EnvironmentKey<VideoStyle> VIDEO_STYLE = EnvironmentKey.of("videoStyle");
    private static final ThreadLocal<EnvironmentValues> VALUES = ThreadLocal.withInitial(EnvironmentValues::empty);

    /** The default environment (no persistent state; buttons render with {@link PlainButtonStyle}). */
    public static final Environment DEFAULT = new Environment(null);

    private final dev.pathland.view.state.PersistentState state;

    public Environment(dev.pathland.view.state.PersistentState state) {
        this.state = state;
    }

    /**
     * The button style active for the current render — the scoped environment value
     * {@link #BUTTON_STYLE}, defaulting to {@link PlainButtonStyle} when no scope
     * binds it.
     */
    public ButtonStyle buttonStyle() {
        ButtonStyle style = Environment.value(BUTTON_STYLE).get();
        return style != null ? style : PlainButtonStyle.INSTANCE;
    }

    /** The session's persistent state (null for a stateless environment). */
    public dev.pathland.view.state.PersistentState state() {
        return state;
    }

    /**
     * The label style active for the current render — the scoped environment value
     * {@link #LABEL_STYLE}, defaulting to {@link DefaultLabelStyle} when no scope
     * binds it.
     */
    public LabelStyle labelStyle() {
        LabelStyle style = Environment.value(LABEL_STYLE).get();
        return style != null ? style : DefaultLabelStyle.INSTANCE;
    }

    /**
     * The audio style active for the current render — the scoped environment value
     * {@link #AUDIO_STYLE}, defaulting to {@link NativeAudioStyle}.
     */
    public AudioStyle audioStyle() {
        AudioStyle style = Environment.value(AUDIO_STYLE).get();
        return style != null ? style : NativeAudioStyle.INSTANCE;
    }

    /**
     * The video style active for the current render — the scoped environment value
     * {@link #VIDEO_STYLE}, defaulting to {@link NativeVideoStyle}.
     */
    public VideoStyle videoStyle() {
        VideoStyle style = Environment.value(VIDEO_STYLE).get();
        return style != null ? style : NativeVideoStyle.INSTANCE;
    }

    // --- generic environment values ---

    /** The current scope (empty at the top of a render). */
    public static EnvironmentValues current() {
        return VALUES.get();
    }

    /**
     * The scoped value for {@code key} as a signal ({@code @Environment},
     * reactive) — the single way to read an environment value.
     *
     * <p>When {@code key} is bound in the current scope, the concrete binding is
     * returned: an injected {@link Signal} comes back as the same instance (bindable
     * for reactive updates, and its {@code WritableSignal} capability is preserved),
     * a plain value is wrapped in a constant signal. When the key is <em>not</em> yet
     * bound — e.g. read in a field initializer before the enclosing
     * {@code EnvironmentBinding} scope is pushed — a lazy {@link EnvironmentSignal} is
     * returned instead, which resolves the key on each {@code .get()} and keeps the
     * last captured binding.
     *
     * <pre>{@code
     * Router router = Environment.value(Navigation.ROUTER).get();  // one-off read
     * Text.make(t -> t.text(Environment.value(Platform.ACTIVE_PATH)));  // reactive binding
     * // field style (resolved at render time, inside the pushed scope):
     * private final Signal<Router> router = Environment.value(Navigation.ROUTER);
     * }</pre>
     */
    public static <T> Signal<T> value(EnvironmentKey<T> key) {
        EnvironmentValues scope = VALUES.get();
        if (scope.contains(key)) {
            return toSignal(scope.get(key));
        }
        return new EnvironmentSignal<>(key);
    }

    /** A {@link Signal} as-is; any other value wrapped in a constant signal. */
    @SuppressWarnings("unchecked")
    private static <T> Signal<T> toSignal(Object value) {
        if (value instanceof Signal<?> s) {
            return (Signal<T>) s;
        }
        return () -> (T) value;
    }

    /**
     * A lazy, scope-resolving environment read: created when the key is not yet bound,
     * it captures the binding on the first {@code .get()} where the key is bound
     * (nearest wins) and reuses it afterwards — so a field initializer resolves at
     * render time, and reads outside render (e.g. the emitter's binding effects) keep
     * the captured binding.
     */
    private static final class EnvironmentSignal<T> implements Signal<T> {

        private final EnvironmentKey<T> key;
        private Signal<T> captured; // the resolved binding, or null if never resolved

        EnvironmentSignal(EnvironmentKey<T> key) {
            this.key = key;
        }

        @Override
        public T get() {
            EnvironmentValues scope = VALUES.get();
            if (scope.contains(key)) {
                captured = toSignal(scope.get(key));
            }
            return captured == null ? null : captured.get();
        }
    }

    /** Temporarily set the active scope for a render (save/restore around it). */
    public static void within(EnvironmentValues scope) {
        VALUES.set(scope);
    }

    /** Restore the previous active scope (must pair with a prior {@link #within}). */
    public static void restore(EnvironmentValues previous) {
        VALUES.set(previous);
    }
}

